-- =====================================================================
-- Module 5: Remote MySQL Database Schema
-- Table: wholesale_products
-- Description: Stores 54-column wholesale catalog analysis records
--              generated by Module 2 (Analyze & Prepare Data).
-- Engine: MySQL / MariaDB (InnoDB, utf8mb4)
-- =====================================================================

CREATE TABLE IF NOT EXISTS wholesale_products (
    id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,

    -- Identification & Supplier
    asin VARCHAR(64) DEFAULT '',
    parent_asin VARCHAR(64) NULL,
    product_id VARCHAR(64) NULL,
    favorite TINYINT(1) DEFAULT 0,
    wholesaler_company_name VARCHAR(255) DEFAULT 'Default Wholesale',

    -- Product Metadata
    brand VARCHAR(255) NULL,
    brand_restriction VARCHAR(255) NULL,
    selling_restriction VARCHAR(255) NULL,
    selling_restriction_link TEXT NULL,
    title TEXT NULL,
    package_quantity INT NULL,
    amazon_link TEXT NULL,
    about_this_item LONGTEXT NULL,

    -- Categorization & Hierarchy
    category VARCHAR(255) NULL,
    is_top_level_category VARCHAR(32) NULL,
    sales_rank INT NULL,
    sub_category VARCHAR(255) NULL,
    sub_category_sales_rank INT NULL,

    -- Pricing, Costs & Revenues
    cost DOUBLE NULL,
    sell_price DOUBLE NULL,
    break_even_sell_price DOUBLE NULL,
    buybox_landed DOUBLE NULL,
    lowest_fba DOUBLE NULL,
    lowest_fbm DOUBLE NULL,
    seller_proceeds DOUBLE NULL,
    current_est_sales INT NULL,
    estimated_monthly_revenue DOUBLE NULL,
    profit DOUBLE NULL,
    margin_pct DOUBLE NULL,
    roi_pct DOUBLE NULL,

    -- Fees Breakdown
    referral_fee_pct DOUBLE NULL,
    referral_fee DOUBLE NULL,
    fba_pick_pack_fee DOUBLE NULL,
    inbound_placement_fee DOUBLE NULL,
    fulfillment_subtotal DOUBLE NULL,
    cost_subtotal DOUBLE NULL,
    vat_pct DOUBLE NULL,
    vat_amount DOUBLE NULL,
    inbound_shipping_estimate DOUBLE NULL,

    -- Dimensions & Physical Attributes
    package_dimensions VARCHAR(255) NULL,
    package_weight_lb DOUBLE NULL,
    color VARCHAR(255) NULL,
    model VARCHAR(255) NULL,
    size VARCHAR(255) NULL,
    part_number VARCHAR(255) NULL,
    material VARCHAR(255) NULL,
    manufacturer VARCHAR(255) NULL,

    -- Competition & Ratings
    total_offers INT NULL,
    new_fba_offers INT NULL,
    new_fbm_offers INT NULL,
    buybox_contention INT NULL,
    customer_reviews VARCHAR(255) NULL,
    average_rating DOUBLE NULL,
    total_review_count INT NULL,

    -- External Tools & Notes
    is_hazmat VARCHAR(64) NULL,
    keepa TEXT NULL,
    camelcc TEXT NULL,
    custom_notes TEXT NULL,

    -- Product Images (Highest resolution)
    product_image_link_1 TEXT NULL,
    product_image_link_2 TEXT NULL,
    product_image_link_3 TEXT NULL,
    product_image_link_4 TEXT NULL,
    product_image_link_5 TEXT NULL,

    -- Execution Timestamps & Tool Tracking
    analyzing_software_name VARCHAR(128) DEFAULT 'InternalAMZ',
    last_run VARCHAR(64) NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,

    INDEX idx_wholesale_asin (asin),
    INDEX idx_wholesale_product_id (product_id),
    INDEX idx_wholesale_wholesaler (wholesaler_company_name),
    INDEX idx_wholesale_category (category),
    INDEX idx_wholesale_sales_rank (sales_rank),
    INDEX idx_wholesale_profit (profit),
    INDEX idx_wholesale_roi (roi_pct),
    INDEX idx_wholesale_last_run (last_run),
    INDEX idx_wholesale_analyzing_software (analyzing_software_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
